def test_dzn_to_csv(mpmmine: MPMMine):
    train, symbols = get_train_and_symbols(mpmmine, "P012M001I001")

    gecs = Adapter.__new__(Adapter)
    tmp_path = Path(tempfile.mkdtemp(prefix="test_gecs"))

    try:
        csv_path = tmp_path / "training.csv"

        gecs._prepare_csv(train, symbols, csv_path)

        csv = pd.read_csv(csv_path)

        assert "_indexset_shifts_1" not in csv.columns
        assert "_indexset_shifts_2" not in csv.columns
        assert "num_work" not in csv.columns
        assert "num_shifts" not in csv.columns
        assert "shifts#1" not in csv.columns

        for i in range(1, 3830):
            assert f"x#{i}" in csv.columns
            assert (csv[f"x#{i}"] >= 0).all()
            assert (csv[f"x#{i}"] <= 1).all()
        assert "x#0" not in csv.columns
        assert "x#3830" not in csv.columns

        assert "tot_shifts" in csv.columns
        assert (csv["tot_shifts"] == 34).all()

        assert len(csv) == 10

    finally:
        shutil.rmtree(tmp_path, ignore_errors=True)
